import scala.collection.mutable

object Solution {
  class DualHeap(k: Int) {
    // maxHeap for the smaller half
    private val maxHeap = mutable.PriorityQueue.empty[Int]
    // minHeap for the larger half
    private val minHeap = mutable.PriorityQueue.empty[Int](Ordering.Int.reverse)
    // delayed map for lazy removals
    private val delayed = mutable.HashMap.empty[Int, Int].withDefaultValue(0)
    private var maxHeapSize = 0
    private var minHeapSize = 0

    private def prune(heap: mutable.PriorityQueue[Int]): Unit = {
      while (heap.nonEmpty && delayed(heap.head) > 0) {
        val num = heap.head
        delayed(num) -= 1
        if (delayed(num) == 0) delayed.remove(num)
        heap.dequeue()
      }
    }

    private def balance(): Unit = {
      // maxHeap can have one more element than minHeap or equal
      if (maxHeapSize > minHeapSize + 1) {
        val moved = maxHeap.dequeue()
        maxHeapSize -= 1
        minHeap.enqueue(moved)
        minHeapSize += 1
        prune(maxHeap)
      } else if (maxHeapSize < minHeapSize) {
        val moved = minHeap.dequeue()
        minHeapSize -= 1
        maxHeap.enqueue(moved)
        maxHeapSize += 1
        prune(minHeap)
      }
    }

    def insert(num: Int): Unit = {
      if (maxHeap.isEmpty || num <= maxHeap.head) {
        maxHeap.enqueue(num)
        maxHeapSize += 1
      } else {
        minHeap.enqueue(num)
        minHeapSize += 1
      }
      balance()
    }

    def erase(num: Int): Unit = {
      delayed(num) += 1
      if (maxHeap.nonEmpty && num <= maxHeap.head) {
        maxHeapSize -= 1
        if (maxHeap.head == num) prune(maxHeap)
      } else {
        minHeapSize -= 1
        if (minHeap.nonEmpty && minHeap.head == num) prune(minHeap)
      }
      balance()
    }

    def getMedian(): Double = {
      if ((k & 1) == 1) maxHeap.head.toDouble
      else (maxHeap.head.toDouble + minHeap.head.toDouble) / 2.0
    }
  }

  def medianSlidingWindow(nums: Array[Int], k: Int): Array[Double] = {
    val dh = new DualHeap(k)
    val n = nums.length
    val result = new Array[Double](n - k + 1)

    for (i <- 0 until k) {
      dh.insert(nums(i))
    }
    result(0) = dh.getMedian()

    for (i <- k until n) {
      dh.insert(nums(i))
      dh.erase(nums(i - k))
      result(i - k + 1) = dh.getMedian()
    }
    result
  }
}

